import type { Publication } from './publication-manifest';

export const nov07ResearchPublications: readonly Publication[] = [{"publicationStatus": "reviewed", "kind": "research", "slug": "what-does-a-philippines-holiday-calendar-do-to-a-support-coverage-promise", "title": "What does a Philippines holiday calendar do to a support coverage promise?", "description": "A method for testing whether a published support coverage promise survives Philippine holidays, local observances, and the client's own closure calendar.", "published": "2026-11-07", "readingMinutes": 7, "heroImage": "/hero/november-7/what-does-a-philippines-holiday-calendar-do-to-a-support-coverage-promise-hero.webp", "thumbnail": "/thumbnails/november-7/what-does-a-philippines-holiday-calendar-do-to-a-support-coverage-promise.webp", "heroAlt": "What does a Philippines holiday calendar do to a support coverage promise?", "topic": "holiday coverage promise", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/plan-holiday-coverage-for-a-philippines-based-assistant-team", "label": "Read the holiday coverage planning guide"}, "sources": [{"label": "Philippine Official Gazette", "href": "https://www.officialgazette.gov.ph/"}, {"label": "Department of Labor and Employment, Philippines", "href": "https://www.dole.gov.ph/"}, {"label": "International Labour Organization", "href": "https://www.ilo.org/"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks what a Philippines holiday calendar does to a published support coverage promise. The unit is a promise that names a response window, a coverage hour, or a resolution target. The scope covers promises in a proposal, a contract, or a public service page that a buyer could rely on. The review does not estimate performance for a particular provider or team.", "A holiday can change the meaning of a promise in three ways. The team may be closed while the client is open, the client may be closed while the team is working, or both may close on different dates. Each case produces a different gap between the promise and the service the buyer actually receives. The review treats the calendar as part of the service definition.", "The review also separates a national holiday from a local observance that affects transport, banking, or childcare. A team may be scheduled to work while a local closure makes the shift unreliable. The calendar should record both the legal holiday and the practical disruption. A promise tested only against national dates will miss the days that hurt most.", "The evidence standard should state whether the promise applies to a dedicated assistant, a shared queue, or a managed team. Each model has a different replacement path when one person is away. The review records the model before it compares the promise with the calendar. A promise that works for a team may fail for a single dedicated role."]}, {"id": "definitions-and-unit", "heading": "Definitions and unit", "paragraphs": ["A coverage promise is a written statement that a request will receive a response or a resolution within a stated period. The clock start, the covered hours, the time zone, and the exclusions are part of the promise. A target without a remedy is a goal rather than a commitment. The review records which document governs and whether the provider can change it without notice.", "A holiday is a date the provider treats as non-working, whether or not the government declares it. A local observance is a date that affects attendance or infrastructure without closing the provider officially. The review records both because the buyer experiences the effect rather than the label. A provider that publishes only national holidays may still lose a day to a local festival.", "The unit of analysis is one promise on one date. That unit lets the review compare a normal week with a holiday week without averaging away the disruption. Record the request type as well, because a password reset and a refund follow different paths. A promise that holds for one category may fail for another."]}, {"id": "evidence-collection", "heading": "Evidence collection", "paragraphs": ["Collect the current promise, the provider's holiday calendar, and the client's holiday calendar. Save a dated copy of each because a website or a calendar can change without a version note. Record the document that governs when the sources disagree. A proposal may promise a coverage window that the contract later narrows.", "Ask the provider which holidays the assigned team observes and whether a holiday shift is optional. Ask the client which dates it treats as closures and which it treats as normal business days. Put the two answers beside the dates rather than in a separate policy note. The comparison should show the days when one side is working and the other is not.", "Collect one or two examples of work that continued through a holiday and one example that did not. Ask for the request date, the response date, and the person who handled it. The examples show whether the written calendar matches the operating habit. They also reveal whether a backup covered the work or the request simply waited."]}, {"id": "patterns-to-measure", "heading": "Patterns to measure", "paragraphs": ["Measure the number of promised hours that fall on a provider holiday and the number that fall on a client holiday. Separate the two counts because they create different risks. A provider holiday can leave a client request unread, while a client holiday can leave the assistant with no one to approve an exception. The pattern shows where the promise needs a named owner.", "Measure the time to first response on the working day before and after a holiday. A backlog often appears before the closure as the team tries to clear the queue. The day after the holiday may be slower than the holiday itself. A single holiday-day measure will miss the surrounding effect.", "Measure the share of holiday work handled by the named backup rather than the primary assistant. A plan that depends on one person is not a coverage plan. Record whether the backup had the access and the context to finish the work. A backup who can only acknowledge a request is a partial control."]}, {"id": "comparing-coverage-models", "heading": "Comparing coverage models", "paragraphs": ["Compare at least two models, such as a full holiday pause, a named on-call assistant, and a shared queue with extended hours. Hold the request mix and the client calendar as constant as the data allow. Count missed promises per hundred requests rather than per holiday. A single holiday can produce a dramatic count that does not describe the normal risk.", "A model that keeps every promise may cost more than the client wants to pay for a quiet day. A model that pauses work may be acceptable when the client also closes. The review should state the trade-off rather than recommend the strongest coverage in every case. The right model depends on the consequence of a one-day delay.", "Record the approval path for holiday work, including who can authorize a short shift or an exception. A model with no budget or authority will fail on the first unexpected request. The comparison should include the decision owner, not only the staffing level. Coverage is a combination of people, access, and permission."]}, {"id": "limits-and-confounders", "heading": "Limits and confounders", "paragraphs": ["A retrospective calendar review cannot show what would have happened under a different staffing model. It can show whether the recorded work matched the written promise. Seasonal volume, a product launch, and a client outage can all affect the same holiday week. Record those events beside the result before drawing a conclusion.", "Holiday calendars can change after the review, especially when a government moves a date. A calendar that was correct at the start of the year may be wrong by December. State the version and the date of the calendar used in the sample. The finding applies to that version rather than to every future year.", "The provider may not control the client's holiday calendar or the client's approval path. A missed promise may come from the client side rather than the assistant. Keep the two calendars separate in the report so the reader can see where the gap occurred. Blaming the provider for a client closure is not a useful finding."]}, {"id": "reporting-the-finding", "heading": "Reporting the finding", "paragraphs": ["Report the promise, the two calendars, the measured gap, and the model used for coverage. Show two or three dated examples that illustrate the pattern. Name the decision owner for the next holiday and the change that will be tested. Avoid a single average that hides the difference between a provider closure and a client closure.", "State the limits before the recommendation so the reader knows what the sample can support. If the evidence is too thin, describe the pattern and ask for more data rather than publishing a rate. A cautious finding is more useful than a precise number built on mismatched calendars. The report should help a buyer ask a better question.", "End with a short checklist for the next holiday, including the dates, the critical work, the owner, the backup, and the confirmation step. Give the checklist to the client and the assistant in the same format. A finding that never reaches the operating calendar will not change the next outcome. The report is complete when someone owns the next review."]}, {"id": "practical-checklist", "heading": "Practical checklist", "paragraphs": ["Ask the provider for the current holiday calendar and the name of the person who maintains it. Ask which dates require a named owner and which can pause. Confirm the client's own closures in writing. Put the answers in one calendar that both parties can read.", "Test one low-stakes holiday before a critical deadline. Record the requests, the response times, and the owner who handled each one. Fix the access or the approval path before the next holiday. Repeat the test after the fix rather than assuming the change worked.", "Review the promise itself after the test. A promise that cannot survive the real calendar should be narrowed or rewritten. A promise that survives should be documented with the coverage model that made it work. The calendar and the contract should tell the same story."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "how-often-do-refund-requests-exceed-a-support-assistants-written-authority", "title": "How often do refund requests exceed a support assistant's written authority?", "description": "A coding method for finding refund and discount requests that pass an assistant's written authority, separating missing limits from missing evidence and late approval.", "published": "2026-11-07", "readingMinutes": 7, "heroImage": "/hero/november-7/how-often-do-refund-requests-exceed-a-support-assistants-written-authority-hero.webp", "thumbnail": "/thumbnails/november-7/how-often-do-refund-requests-exceed-a-support-assistants-written-authority.webp", "heroAlt": "How often do refund requests exceed a support assistant's written authority?", "topic": "refund authority gaps", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/set-refund-and-discount-boundaries-for-a-support-assistant", "label": "Read the refund and discount boundary guide"}, "sources": [{"label": "FTC truth in advertising", "href": "https://www.ftc.gov/business-guidance/resources/truth-advertising"}, {"label": "FTC advertising and marketing basics", "href": "https://www.ftc.gov/business-guidance/advertising-marketing"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how often refund and discount requests exceed a support assistant's written authority. The unit is a customer request that asks for money back, a price change, or a waived fee. The scope covers requests handled through email, chat, and the task board. The review measures the written limit, not whether the customer deserved the outcome.", "A request can exceed authority in amount, in type, or in evidence. An assistant may be allowed to approve a small refund but not a discount, or a refund with a receipt but not one without a record. The review codes each dimension separately so the result shows which limit failed. A single count would hide the difference between a missing rule and a missing document.", "The review also separates a request that was escalated from one that should have been escalated. An assistant may escalate a routine case out of caution, while another may approve an exception without realizing a limit exists. Both patterns matter, but they lead to different fixes. The report should show both the overreach and the unnecessary escalation.", "The review should state whether it covers one client or several. A shared authority table may not fit every client's policy, especially when the client sells through more than one channel. Record the client and the channel for every request. A pooled rate across clients can hide a rule that works for one and fails for another."]}, {"id": "definitions-and-unit", "heading": "Definitions and unit", "paragraphs": ["Written authority means the limit stated in a current document that the assistant can access during the task. A verbal permission from a manager is not written authority unless it is recorded in the same system. A limit that exists only in a training slide is not usable during a live chat. The review records the document, the version, and the date.", "A refund is a return of money already paid, while a discount is a reduction applied before or after payment. A credit may be either, depending on how the client records it. The review codes the financial action rather than the label the customer uses. Two requests with the same label can follow different approval paths.", "The unit is one request and one decision. A request that receives a partial refund and a separate discount is two decisions, not one. Record the amount, the currency, the evidence attached, and the person who approved the final action. The unit keeps the count from doubling when a request is split across messages."]}, {"id": "evidence-collection", "heading": "Evidence collection", "paragraphs": ["Select requests from at least two weeks and several agents, including one busy period. Use the ticket export, the payment record, and the authority document together. Where the records disagree, keep both and mark the case as disputed. The sample should be small enough to read each request in full.", "Record the request date, the amount, the customer's stated reason, and the evidence the assistant had at the time. Do not judge the case with information that arrived after the decision. The review is about the authority available then, not the wisdom of the outcome now. A later document can explain a gap but cannot change the coding.", "Ask the assistant which limit caused the most hesitation during the sample period. Their answer may reveal a rule that is technically clear but difficult to apply. Add the example to the evidence set and read the actual message. A rule that nobody can apply during a live chat is a rule that needs rewriting."]}, {"id": "patterns-to-measure", "heading": "Patterns to measure", "paragraphs": ["Measure the share of requests that exceeded the written amount, the written type, or the evidence requirement. Keep the three counts separate and show the overlap. A request can exceed more than one limit, and the overlap often points to the simplest fix. The distribution is more useful than a single total.", "Measure the time between the request and the approval for cases that were escalated. A limit that is clear but slow to approve creates a different problem from a limit that is missing. Compare the delay with the customer's expectation and the published response window. A fast decision path can be as important as a generous limit.", "Measure the share of decisions that were reversed later by a manager or a finance review. A reversed decision is evidence that the authority table and the actual policy disagree. Read a sample of reversals and code the cause. Reversals are expensive because they combine a customer conversation with a financial correction."]}, {"id": "comparing-authority-models", "heading": "Comparing authority models", "paragraphs": ["Compare a small fixed limit with a tiered limit that depends on the request type or the customer's history. Hold the product and the customer segment as constant as the data allow. Count both the overreach and the escalation rate. A model that stops overreach by escalating everything has moved the cost rather than removed it.", "A tiered model can fit a business with several products, but it needs a clear table and a named owner for each tier. A fixed limit is easier to remember but may be too small for routine cases. The review should state which model the evidence supports for the actual request mix. The goal is a decision the assistant can make at the moment of contact.", "Record the approval path for an exception, including the person, the channel, and the expected response time. A model without a named exception owner will fail on the first unusual case. The comparison should include the cost of waiting as well as the cost of the refund. A generous limit that takes two days to approve may still lose the customer."]}, {"id": "limits-and-confounders", "heading": "Limits and confounders", "paragraphs": ["A retrospective sample cannot show what would have happened if the assistant had a different limit. It can show whether the recorded decision matched the written rule. A policy change during the sample can make an old decision look wrong. Record the version and the date of the authority document for every case.", "The sample may miss requests that were resolved in a chat and never entered the ticket system. Those cases may be legitimate, but they are outside the evidence. State the boundary and the number of unrecorded cases if the team can estimate them. Do not treat a missing record as proof of a good or bad decision.", "Finance and support may define the same refund differently. A finance credit and a support refund can appear in different reports with different amounts. Reconcile the definitions before comparing counts across teams. A comparison built on two definitions will produce a precise but misleading result."]}, {"id": "reporting-the-finding", "heading": "Reporting the finding", "paragraphs": ["Report the overreach rate, the escalation rate, the reversal rate, and the main cause for each. Show two anonymized examples that illustrate the most common pattern. Recommend one change, such as a clearer amount table or a required evidence field. Name the owner and the measure that will show whether the change worked.", "Separate a missing rule from a rule that the assistant could not find. The first needs a policy decision, while the second needs a workspace or training fix. A report that merges them will produce a training program for a documentation problem. The distinction keeps the remedy small enough to finish.", "Recheck a small sample after the change and compare the same measures. If overreach falls but escalation rises, the new limit may be too tight or the approval path too slow. Adjust the limit or the path before adding another rule. The finding is complete when the assistant can resolve the routine case and recognize the exception."]}, {"id": "practical-checklist", "heading": "Practical checklist", "paragraphs": ["Write the amount, the request type, the evidence, and the approval owner in one table. Put the table where the assistant works, not in a separate policy folder. Give one example of an approved case and one example of an exception. Test the table with the next ten live requests.", "Review the first month of decisions with the assistant and a finance owner. Mark the cases that should become policy and the cases that should stay exceptions. Remove limits that no longer match the business. Keep the version date beside the table.", "Set a monthly review and sample both routine and exception cases. Ask the assistant which rule caused the most hesitation. Fix that rule before adding more training. The authority table should get shorter and clearer as the team learns."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "can-a-client-tone-guide-be-validated-against-sent-email-samples", "title": "Can a client tone guide be validated against sent email samples?", "description": "A validation method that compares a written tone guide with the client's actual sent messages, separating voice, commitments, and approval language.", "published": "2026-11-07", "readingMinutes": 7, "heroImage": "/hero/november-7/can-a-client-tone-guide-be-validated-against-sent-email-samples-hero.webp", "thumbnail": "/thumbnails/november-7/can-a-client-tone-guide-be-validated-against-sent-email-samples.webp", "heroAlt": "Can a client tone guide be validated against sent email samples?", "topic": "tone guide validation", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/write-a-client-tone-guide-a-virtual-assistant-can-actually-use", "label": "Read the client tone guide writing guide"}, "sources": [{"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}, {"label": "FTC truth in advertising", "href": "https://www.ftc.gov/business-guidance/resources/truth-advertising"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks whether a client tone guide can be validated against the client's actual sent messages. The unit is one written rule and one matching sample from the sent folder. The scope covers email and chat replies that reach a customer or a client contact. The review does not measure whether the guide is attractive or whether a customer liked the reply.", "A guide can be internally consistent and still describe a voice the client never uses. Validation checks the guide against evidence rather than against the writer's memory. It also checks whether the guide covers the cases that appear in real messages. A guide that only matches the easy samples is not ready for live work.", "The review separates three questions. Does the guide describe the voice the client actually uses, does it state the commitments the client is willing to make, and does it tell the assistant when to stop? Each question needs its own evidence. Combining them into one score hides the part that failed.", "The review should state whether it covers one client or several. A provider may write one guide for a team that serves clients with different voices. In that case, the unit should be the client and the guide version. A pooled sample across clients will produce a rule that fits none of them."]}, {"id": "definitions-and-unit", "heading": "Definitions and unit", "paragraphs": ["A tone rule is a statement about greetings, warmth, pacing, directness, or closing language. A commitment rule is a statement about what the assistant may promise, such as a delivery date, a refund, or a follow-up time. The review codes the two types separately because a stylistic sample cannot validate a promise. A guide that mixes the two leaves the assistant unsure which line can be changed and which line must be approved.", "A validated rule has at least two matching sent samples and no clear contradiction. A contradicted rule has a sent sample that follows the opposite practice without a stated exception. An untested rule has no sample or only a sample from a different context. The review records the code and the evidence for each rule.", "The sample unit is one message, not one thread. A thread may contain several replies with different purposes, such as an acknowledgement and a resolution. Code the message that demonstrates the rule. A thread-level count can hide the exact sentence that supports or contradicts the guide."]}, {"id": "evidence-collection", "heading": "Evidence collection", "paragraphs": ["Collect the current guide and a dated set of sent messages from the last three months. Include routine replies, delays, corrections, and at least one refusal. Remove customer names and sensitive details before sharing the sample. Keep the original locator so a reviewer can trace the message without storing the personal data.", "Select messages from more than one writer if the client has a team. A guide based on one person's style may not represent the voice the client wants from a new assistant. Record the writer's role and the message purpose. A founder's reply to a friend is not the same evidence as a support reply to a stranger.", "Ask the client to mark any message that they would not want copied. A rejected sample is useful because it shows the boundary of the voice. Record the reason in the client's words rather than the reviewer's interpretation. The reason becomes a rule that the assistant can apply to a new message."]}, {"id": "validation-method", "heading": "Validation method", "paragraphs": ["For each rule, find at least two messages that follow it and check for messages that contradict it. If a contradiction exists, ask whether it is an approved exception or a sign that the rule is wrong. Update the rule or add the exception before testing the guide with an assistant. A rule that survives this check is more likely to survive live work.", "Score the guide on coverage as well as accuracy. Count the common message types in the sample and check whether the guide has a rule or an example for each. A guide can be accurate for the messages it covers and still leave the hard cases unaddressed. The coverage gap is often more dangerous than a slightly different greeting.", "Test the guide by asking a second writer to draft replies from the sample cases without seeing the originals. Compare the drafts with the sent messages and with the guide. Differences show where the guide is ambiguous or where the writer applied a different judgment. The test is about the guide, not the writer's talent."]}, {"id": "patterns-to-look-for", "heading": "Patterns to look for", "paragraphs": ["Look for rules that describe an aspiration rather than a behavior, such as be empathetic or sound professional. Those words are hard to apply and hard to verify. Replace them with an observable action, such as name the customer's issue in the first sentence. A rule the reviewer can point to in a message is a usable rule.", "Look for commitments hidden inside friendly language. A phrase such as we will take care of it can read as a promise even when the guide treats it as a courtesy. Mark every sentence that changes what the customer expects. The commitment rules should be explicit even when the voice is warm.", "Look for exceptions that appear often enough to become the rule. A guide that says always reply within one day but includes a holiday exception used every month needs a clearer calendar rule. Count the exceptions in the sample rather than treating each one as a one-off. The pattern shows where the guide and the operation disagree."]}, {"id": "limits-and-confounders", "heading": "Limits and confounders", "paragraphs": ["Sent messages are selected because they were sent, not because they were good. A sample can include replies that the client regrets or that a manager later corrected. The review should ask for the client's judgment rather than assuming every sent message is a model. A message that exists is evidence of practice, not necessarily of standard.", "The sample may be too small to represent a seasonal or a high-volume period. A guide validated on quiet-week messages may fail during a launch or a billing cycle. Record the period and the volume beside the sample. If the guide has no rule for the busy case, mark the gap rather than extrapolating.", "The reviewer may share the client's taste and score the guide as more consistent than an outsider would. Use a second reviewer or a written rubric to reduce that risk. Keep the evidence beside the score so another person can challenge the judgment. Validation is stronger when it can be repeated."]}, {"id": "reporting-the-finding", "heading": "Reporting the finding", "paragraphs": ["Report the rules validated, the rules contradicted, and the common message types with no rule. Show two anonymized examples that explain the difference. Recommend one change to the guide and one change to the sample set. Avoid a single score that hides which part of the guide is weak.", "State the limits of the sample before the recommendation. If the client has several voices, report them separately rather than averaging them. A guide that is strong for support and weak for billing needs a different fix in each area. The report should help the client decide where to spend the next editing hour.", "Recheck the revised guide against a fresh sample after two weeks of use. Add the cases that the assistant found confusing and remove the rules that produced awkward drafts. The validation is complete when the guide and the sent messages tell the same story. A guide that needs a manager to interpret every rule is not yet usable."]}, {"id": "practical-checklist", "heading": "Practical checklist", "paragraphs": ["Collect the current guide, the sent sample, and the client's rejected examples. Code each rule as validated, contradicted, or untested. Check coverage for the common message types and the hard cases. Record the evidence for every code.", "Ask a second writer to draft from the sample without seeing the originals. Compare the drafts with the guide and the sent messages. Fix the ambiguous rule before the next live reply. Keep the strongest examples beside the rule.", "Review the guide after the first month of live work. Add one new example and remove one rule that no longer fits. Keep the version date and the owner. A short guide that matches the sent folder is better than a long guide that describes a voice the client never uses."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "what-does-calendar-hygiene-reveal-about-who-owns-a-meeting", "title": "What does calendar hygiene reveal about who owns a meeting?", "description": "A method for reading meeting ownership from calendars, recurring invitations, preparation blocks, and follow-up notes without relying on job titles.", "published": "2026-11-07", "readingMinutes": 7, "heroImage": "/hero/november-7/what-does-calendar-hygiene-reveal-about-who-owns-a-meeting-hero.webp", "thumbnail": "/thumbnails/november-7/what-does-calendar-hygiene-reveal-about-who-owns-a-meeting.webp", "heroAlt": "What does calendar hygiene reveal about who owns a meeting?", "topic": "meeting ownership", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/review-a-virtual-assistants-calendar-for-meeting-hygiene", "label": "Read the calendar meeting hygiene guide"}, "sources": [{"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "U.S. Bureau of Labor Statistics", "href": "https://www.bls.gov/"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks what a calendar can reveal about who owns a meeting and whether that ownership is real. The unit is one recurring or one-off meeting that appears on an assistant's calendar. The scope covers the invitation, the attendee list, the agenda, the preparation time, and the follow-up note. The review measures ownership signals, not meeting quality in general.", "A meeting can have a named organizer and no decision owner. The organizer sends the invitation, while the decision owner is the person who can change the outcome or approve the next step. The review records both roles because a calendar often shows only the first. A meeting without a decision owner tends to produce updates rather than outcomes.", "The review also separates a meeting the assistant attends from one the assistant prepares or schedules. Each role consumes different time and creates different access needs. A calendar that treats all three as attendance will hide the preparation work. The review records the role beside every event.", "The evidence standard should state whether the review covers one assistant, one client, or a team. A team calendar may show a meeting that one person owns and another attends as backup. The unit should follow the decision rather than the invitation list. A pooled count across roles can make ownership look clearer than it is."]}, {"id": "definitions-and-unit", "heading": "Definitions and unit", "paragraphs": ["A meeting owner is the person accountable for the agenda, the decision, and the follow-up. A meeting organizer is the person who created the invitation and manages the logistics. A facilitator is the person who runs the discussion but may not own the outcome. The review codes these roles separately and records the evidence for each.", "A decision is a choice that changes a commitment, a resource, or a next action. A status update is information that does not require a choice. The review codes the meeting output as a decision, an update, or unclear. A recurring meeting that only produces updates may not need the same cadence or the same attendees.", "The unit is one event on one calendar. A recurring series counts as one event, but each occurrence can be sampled for output. The review records the series owner and the occurrence output because a series can drift after the original owner leaves. The distinction prevents the calendar from looking healthy because the invitation still exists."]}, {"id": "evidence-collection", "heading": "Evidence collection", "paragraphs": ["Export the calendar events for a four-week window, including the organizer, attendees, recurrence, and description. Pair the export with the agenda and the follow-up note for a sample of meetings. Where no agenda or note exists, record the absence rather than inferring the content. The evidence should let a second reviewer see the same ownership signals.", "Read the invitation description for a stated purpose and a required output. A description that only repeats the meeting title is a weak ownership signal. Check whether the invitation names a decision or a preparer. A meeting with a clear purpose is easier to review than one that exists because it always has.", "Ask the assistant which meetings they prepare for and which they only attend. Their answer may reveal hidden work that the calendar does not show. Add the preparation and follow-up time to the event record. A meeting that takes thirty minutes but requires two hours of preparation is not a thirty-minute commitment."]}, {"id": "patterns-to-measure", "heading": "Patterns to measure", "paragraphs": ["Measure the share of meetings with a named decision owner, a stated output, and a follow-up note. Keep the three measures separate because they fail in different ways. A meeting can have an owner and no note, or a note and no decision. The pattern shows where the calendar is only a scheduling record.", "Measure the number of recurring meetings that have not changed their attendee list or agenda in several months. A stale series is a candidate for a shorter cadence or a written update. Compare the series with the decisions it produced in the sample. A series that produces no decision is a cost without a clear return.", "Measure the preparation and follow-up time as a share of the meeting time. A meeting that requires more preparation than the meeting itself may be worth keeping, but the calendar should show the work. An assistant who is booked back-to-back has no room to prepare or to write the note. The calendar should reflect the real cost of the meeting."]}, {"id": "comparing-ownership-models", "heading": "Comparing ownership models", "paragraphs": ["Compare a model where the assistant owns the logistics with one where the assistant also owns the follow-up note. The first keeps the calendar accurate, while the second creates a record of decisions and actions. Hold the meeting type constant as the data allow. A note-owning model may reduce repeated questions, but it also adds work.", "Compare a model with a named backup against one where the organizer is the only contact. A backup can keep the meeting useful when the owner is away, but the backup needs the context and the authority to act. The review should record whether the backup attended or only received the invitation. An invitation without context is not a backup plan.", "Record the cost of a meeting that lacks an owner. The cost may appear as a repeated question, a missed action, or a second meeting to decide what the first meeting did not. A comparison that only counts attendance misses the rework. The ownership model should be judged by the decisions it produces."]}, {"id": "limits-and-confounders", "heading": "Limits and confounders", "paragraphs": ["A calendar is a plan, not a record of what happened. A meeting may have produced a decision in a chat after the event, and the note may live somewhere else. The review should pair the calendar with the actual follow-up record. A missing note is a documentation gap, not proof that no decision occurred.", "The sample may be too small to represent a quarter or a busy season. A calendar reviewed during a quiet month may look cleaner than the same calendar during a launch. Record the period and the volume beside the result. Do not publish a rate that the sample cannot support.", "The reviewer may know the team and fill in an owner from memory. That knowledge is useful for explanation but dangerous for measurement. Require a written name or a recorded decision before coding a meeting as owned. The stricter rule keeps the finding reproducible by someone outside the team."]}, {"id": "reporting-the-finding", "heading": "Reporting the finding", "paragraphs": ["Report the share of meetings with a decision owner, a stated output, and a follow-up note. Show two anonymized examples that illustrate the difference between a well-owned meeting and a meeting that only exists. Recommend one calendar change, such as a required output field or a shorter cadence. Name the owner and the next review date.", "Separate a meeting that lacks an owner from a meeting whose owner is on leave. The first needs a structural fix, while the second needs a backup. A report that merges them will recommend a new process for a temporary absence. The distinction keeps the remedy proportionate.", "Recheck the calendar after one cycle and compare the same measures. If the number of meetings falls but the decisions do not, the change may have removed the wrong events. If the notes improve but attendance grows, the meeting may need a clearer purpose. The finding is complete when the calendar and the decision record agree."]}, {"id": "practical-checklist", "heading": "Practical checklist", "paragraphs": ["List the recurring meetings and name the decision owner for each one. Mark the meetings that only produce updates. Check whether the invitation states a purpose and an output. Add preparation and follow-up time to the calendar.", "Test one shorter cadence or one written update in place of a meeting. Compare the decisions and the questions that follow. Keep the change if the output holds and the cost falls. Restore the meeting if a decision disappears.", "Review the calendar again in a month and read the follow-up notes. Ask the assistant which meeting felt unnecessary and which one needed more preparation. Fix one item before adding another rule. The calendar should show the work that matters, not every hour that can be booked."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "how-reproducible-is-a-task-card-built-from-a-client-sop", "title": "How reproducible is a task card built from a client SOP?", "description": "A test protocol for checking whether a one-page task card lets a different assistant reproduce a client SOP without the original manual.", "published": "2026-11-07", "readingMinutes": 7, "heroImage": "/hero/november-7/how-reproducible-is-a-task-card-built-from-a-client-sop-hero.webp", "thumbnail": "/thumbnails/november-7/how-reproducible-is-a-task-card-built-from-a-client-sop.webp", "heroAlt": "How reproducible is a task card built from a client SOP?", "topic": "task card reproducibility", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/turn-a-client-sop-into-a-one-page-task-card", "label": "Read the SOP task card writing guide"}, "sources": [{"label": "NIST SP 800-128, Guide for Security-Focused Configuration Management", "href": "https://csrc.nist.gov/pubs/sp/800/128/final"}, {"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks whether a one-page task card can let a different assistant reproduce a client SOP without the original manual. The unit is one task completion by one assistant using the card. The scope covers the trigger, the steps, the tools, the examples, and the stop rules. The review measures reproducibility, not whether the card is well written in general.", "A card can be clear to the person who wrote it and ambiguous to everyone else. Reproducibility is tested by giving the card to someone who did not write it and comparing the output with the standard. The test should use a safe sample rather than live client data. A card that only works with the author present is a note, not a task card.", "The review also separates a card problem from a tool problem. An assistant may follow the card correctly and still fail because a folder is missing or a permission is wrong. Record the failure point so the remedy matches the cause. A training fix for a tool problem wastes time and erodes trust in the card.", "The evidence standard should state whether the task is routine or exceptional. A routine task can be reproduced from a short card, while an exception may need a decision owner and a different record. The review codes the task type before it scores the output. A card tested only on the routine case may fail the first exception."]}, {"id": "definitions-and-unit", "heading": "Definitions and unit", "paragraphs": ["A task card is a one-page operational summary that names the trigger, the outcome, the steps, the tools, the examples, the stop rules, and the version. A client SOP is the source document the card summarizes. The review records the source version so a later change can be traced. A card without a source version can look current while describing an older procedure.", "Reproducibility means a second assistant produces an output that matches the standard without asking the author for help. The output can differ in wording or layout if the client's standard allows it. The review records the dimensions that must match and the ones that may vary. A card that demands an exact copy may be too rigid for the task.", "The unit is one task completion. If a task has two outputs, such as a file and a message, score them separately. A card can get the file right and the message wrong. The separate scores show which part of the card needs work."]}, {"id": "evidence-collection", "heading": "Evidence collection", "paragraphs": ["Collect the current card, the source SOP, and the standard example. Ask the author to mark the parts of the SOP that the card intentionally leaves out. Those omissions are part of the test because a missing context can change the output. Keep the source version with the card so the comparison is fair.", "Select a tester who has the right tool access but did not write the card. Give the tester the card, the example, and a safe task, with no access to the author. Record the start time, the questions asked, and the points where the tester paused. The pauses are the most useful evidence of a gap.", "Capture the output exactly as the tester saved it, including the file name and location. Compare it with the standard example and note every difference. Ask the tester to explain each difference before the author explains the card. The order keeps the test from becoming a coaching session."]}, {"id": "scoring-reproducibility", "heading": "Scoring reproducibility", "paragraphs": ["Score the trigger, the outcome, the steps, the tool use, the examples, and the stop rules on a simple scale. Use the same scale for every card so the results can be compared. Write one piece of evidence beside each score. A score without evidence is an opinion that is hard to act on.", "Score whether the tester found the right source and applied the right permission. A card that produces the right output through the wrong access is a risk even when the result looks correct. Record the access path beside the output. The review should catch a shortcut that would fail in a live client system.", "Score the time to completion as a secondary measure. A card that takes twice as long as the standard may still be acceptable for a new assistant, but the difference should be understood. Record the questions and the searches that consumed the time. Speed without accuracy is not the goal."]}, {"id": "patterns-to-look-for", "heading": "Patterns to look for", "paragraphs": ["Look for steps that describe a goal rather than an action, such as organize the folder or handle the request. Those steps force the tester to invent a method. Replace them with the exact action and the tool where it happens. A card with one vague step can fail even when the rest is precise.", "Look for examples that show the finished output but not the decisions that produced it. A good example includes the source, the choice, and the reason. Without the reason, the tester can copy the layout and miss the judgment. Add a short note beside the example rather than a longer narrative.", "Look for stop rules that name a person but not a channel or a time. A stop rule that says ask the manager is incomplete when the manager is away. Add the backup, the channel, and the expected response time. The stop rule should work on the day the primary owner is unavailable."]}, {"id": "limits-and-confounders", "heading": "Limits and confounders", "paragraphs": ["A single tester cannot represent every assistant or every level of experience. A card that works for an experienced tester may fail for a new hire. Record the tester's background and run the test with at least one less experienced person when the role allows. The result applies to the tested group, not to everyone.", "The test may be affected by the tester's prior knowledge of the client or the tool. A tester who has done the task before may fill gaps from memory. Ask the tester to mark any step they completed from prior knowledge rather than the card. Those marks reveal hidden assumptions.", "The card may be correct for the sample task and incomplete for a different request type. Test one routine case and one exception if the role handles both. State which case the result covers. A reproducible routine card is useful, but it does not prove the exception path works."]}, {"id": "reporting-the-finding", "heading": "Reporting the finding", "paragraphs": ["Report the dimensions that matched, the gaps the tester found, and the changes made to the card. Show one anonymized output comparison and the questions the tester asked. Recommend one card change and one tool or access change if needed. Name the owner and the next test date.", "Separate a card failure from a tester error. A tester who skipped a step may have missed a clear instruction, or the card may have buried it. Read the card beside the tester's path before assigning blame. The distinction keeps the fix focused on the document.", "Re-test the revised card with a different tester and the same standard. If the output improves, keep the change and remove the old version after the review cycle. If it does not, inspect the source SOP for a missing rule. The card is reproducible when two different people can produce the same acceptable result."]}, {"id": "practical-checklist", "heading": "Practical checklist", "paragraphs": ["Choose one routine task and one exception. Collect the card, the SOP, the example, and the tool access. Give them to a tester who did not write the card. Record the questions, pauses, and output.", "Score the output against the standard and mark every difference. Fix the card before the tool or the training. Test again with a different person. Keep the version that passes.", "Review the card after a month of live use and read the corrections. Remove steps that nobody performs and add the missing detail. Update the version date and the source SOP together. A card that stays reproducible is one that is maintained.", "Compare the card with the client's current procedure before the next busy cycle. A small policy change can make the trigger or a stop rule wrong. Read both documents side by side and mark every line that no longer matches. Update them in the same edit so the assistant never has to choose between two versions."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "what-share-of-downloaded-client-files-outlive-their-retention-date", "title": "What share of downloaded client files outlive their retention date?", "description": "A sampling method for finding downloaded client files kept past their retention date, separating working copies, deliverables, and sensitive records.", "published": "2026-11-07", "readingMinutes": 7, "heroImage": "/hero/november-7/what-share-of-downloaded-client-files-outlive-their-retention-date-hero.webp", "thumbnail": "/thumbnails/november-7/what-share-of-downloaded-client-files-outlive-their-retention-date.webp", "heroAlt": "What share of downloaded client files outlive their retention date?", "topic": "download retention gaps", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/build-a-file-retention-routine-for-a-virtual-assistants-downloads", "label": "Read the download retention routine guide"}, "sources": [{"label": "NIST Privacy Framework", "href": "https://www.nist.gov/privacy-framework"}, {"label": "FTC disposing of your records", "href": "https://www.ftc.gov/business-guidance/resources/disposing-your-records"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "HHS HIPAA Security Rule", "href": "https://www.hhs.gov/hipaa/for-professionals/security/index.html"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks what share of downloaded client files remain past their retention date. The unit is one file or one folder that an assistant downloaded while doing client work. The scope covers browser downloads, desktop copies, chat attachments, and local sync folders. The review measures age against a written retention rule, not whether the file is useful.", "A file can outlive its retention date in one location and be correctly removed from another. The review checks the locations that the rule covers and records the ones it cannot see. A clean shared drive does not prove that a local download folder is empty. The finding should state the coverage of the search.", "The review also separates a working copy from a client deliverable and a record that must be kept. A working copy can be deleted once the deliverable is saved, while a financial or contractual record may need a fixed period. The classification is part of the measurement because the same age means different things in each category. The same physical file can be a working copy for one purpose and a record for another, so the owner should decide before deletion.", "The evidence standard should state whether the review covers one assistant, one client, or a team. A team may have several download habits and several devices. A sample from one laptop will not represent the team. The report should name the population and the locations it actually searched."]}, {"id": "definitions-and-unit", "heading": "Definitions and unit", "paragraphs": ["A retention date is the last day a file may be kept under the client's rule or the provider's policy. The date may be calculated from the file's creation, the end of the engagement, or the last use. The review records the rule and the calculation method. A date without a method cannot be tested.", "A downloaded file is a copy created outside the approved client system, even if it is later moved into a shared folder. The review records the original download location and the current location. A file that was moved is still in scope because the copy may remain in a sync history or a backup. The review checks the copy that is actually present, not only the link to the approved system.", "The unit is one file. A folder counts as one unit only when the rule treats it as a single record, such as a project archive. Otherwise the review samples the files inside the folder. The distinction prevents a large folder from hiding many overdue files."]}, {"id": "evidence-collection", "heading": "Evidence collection", "paragraphs": ["Export a file list from each location with the name, path, size, creation date, last modified date, and owner. Do not open sensitive files during the review. Use metadata and the client's classification list to assign a category. Keep the export read-only and store it with the review date.", "Ask the assistant to describe where they save files during a normal task. Compare the description with the actual folders and note the gaps. A folder that the assistant forgot may be the one with the oldest files. The review should include the forgotten location rather than only the approved one.", "Select a sample across clients, file types, and dates. Include at least one file from a busy period and one from an ended engagement. Read the retention rule for each category before scoring the file. A sample weighted toward recent files will understate the overdue share."]}, {"id": "measuring-overdue-files", "heading": "Measuring overdue files", "paragraphs": ["Count the files whose retention date has passed and that are still present in a covered location. Report the count and the share of the sample, with the confidence limit if the sample supports one. Do not report a team-wide rate from a convenience sample. The measure should be reproducible from the file list.", "Separate files that are overdue by a few days from files that are overdue by months. A short delay may reflect a monthly cleanup cycle, while a long delay suggests the rule is not operating. Report the age distribution rather than only the average. The oldest files are often the ones with the highest sensitivity.", "Check whether an overdue file is a duplicate of a record that is correctly retained elsewhere. A duplicate can be deleted without losing the record, while a unique file may need a review before deletion. Record the duplicate status beside the age. The remedy depends on whether the file is the only copy."]}, {"id": "patterns-to-look-for", "heading": "Patterns to look for", "paragraphs": ["Look for overdue files concentrated in one client, one file type, or one assistant. A cluster on one client may mean the retention rule was never added to the onboarding. A cluster on one file type may mean the approved system cannot handle that format. The pattern points to a process fix rather than a general reminder.", "Look for files that were downloaded for a single meeting and never removed. Those files often contain the most sensitive material because they were shared for a time-limited purpose. Check the meeting date and the last access date. A file that was never opened after the meeting is a strong candidate for deletion.", "Look for folders with no owner and no review date. An unowned folder tends to accumulate files because nobody is responsible for the cleanup. Assign an owner before setting another reminder. The ownership gap is often the reason the rule failed."]}, {"id": "limits-and-confounders", "heading": "Limits and confounders", "paragraphs": ["The file list may not show files stored in a personal cloud account or on a personal device. Those locations are outside the provider's visibility and may hold the oldest copies. State the blind spots rather than treating the visible list as complete. A review that claims full coverage without device access is overstating the evidence.", "Retention rules can change during the sample period. A file that is overdue under the current rule may have been compliant when it was created. Record the rule version and the date it took effect. The finding should distinguish a rule change from a cleanup failure.", "A file's last modified date may reflect a sync event rather than a person opening it. Do not treat the date as proof of use. Use the access log where available and mark the rest as unknown. The limitation matters when a file is kept because someone believes it is still active."]}, {"id": "reporting-the-finding", "heading": "Reporting the finding", "paragraphs": ["Report the overdue share, the age distribution, the locations searched, and the locations that could not be searched. Show two anonymized examples, one working copy and one sensitive record. Recommend one change, such as a daily cleanup, a shorter retention period, or a required deletion confirmation. Name the owner and the next sample date.", "Separate a rule problem from a search problem. A file kept because the rule allows it is not a failure, while a file kept because nobody looked is. The report should show both the compliance rate and the coverage rate. A clean compliance rate on a narrow search is not a strong result.", "Recheck the same locations after the change and compare the overdue share. If the share falls but the sensitive files remain, the cleanup may be targeting the easy files. Review the sensitive category separately. The finding is complete when the routine reaches the files that carry the most risk."]}, {"id": "practical-checklist", "heading": "Practical checklist", "paragraphs": ["List every location where a client file can land. Assign a category and a retention rule to each file type. Export the metadata and mark the files past their date. Record the locations that could not be searched.", "Review the oldest and most sensitive files first. Confirm whether a duplicate exists before deleting a unique record. Record the deletion date and the reviewer. Test the download folder again the next morning.", "Set a monthly sample and a named records owner. Read the exceptions and update the rule when a category no longer fits. Keep the evidence with the routine. A retention routine that cannot show its deletions is only a cleanup habit.", "Review the retention rule when a client adds a new system or a new data category. A tool that stores files in a different location can create a blind spot that the old rule never covered. Add the location to the inventory and test it with a harmless file. A routine that is not updated after a system change will slowly lose coverage."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "does-a-written-english-screen-predict-a-virtual-assistants-document-quality", "title": "Does a written English screen predict a virtual assistant's document quality?", "description": "A validation method for comparing a short untimed writing exercise with the live documents a virtual assistant later produces for a client.", "published": "2026-11-07", "readingMinutes": 7, "heroImage": "/hero/november-7/does-a-written-english-screen-predict-a-virtual-assistants-document-quality-hero.webp", "thumbnail": "/thumbnails/november-7/does-a-written-english-screen-predict-a-virtual-assistants-document-quality.webp", "heroAlt": "Does a written English screen predict a virtual assistant's document quality?", "topic": "written English screen validity", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/screen-a-virtual-assistant-for-written-english-without-a-timed-test", "label": "Read the written English screening guide"}, "sources": [{"label": "EEOC employment tests and selection procedures", "href": "https://www.eeoc.gov/laws/guidance/employment-tests-and-selection-procedures"}, {"label": "O*NET OnLine", "href": "https://www.onetonline.org/"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks whether a short untimed writing exercise predicts the quality of the documents a virtual assistant later produces. The unit is one candidate's exercise and one set of live documents from the same assistant after hire. The scope covers customer replies, internal notes, and short reports. The review measures prediction, not whether the exercise is fair in a legal sense.", "A screen can predict accuracy, structure, tone, or speed, and it may predict some of these better than others. The review scores each dimension separately so a single total does not hide the pattern. A candidate who writes clearly but misses facts is a different risk from one who is accurate but hard to read. The client needs to know which risk the screen detects.", "The review also separates the exercise from the onboarding and the review process. A candidate may score well and still produce weak live work because the brief is unclear or the examples are missing. The live sample should be judged against the same standard as the exercise. A difference between the two is a finding about the role, not only about the person.", "The evidence standard should state whether the review covers one role or several. A customer support reply and an executive brief use different writing skills. A screen validated for one role may not predict the other. The report should name the role and the document types it covers."]}, {"id": "definitions-and-unit", "heading": "Definitions and unit", "paragraphs": ["Document quality means the output meets the role's standard for accuracy, completeness, structure, tone, and required action. The review uses a rubric with observable criteria for each dimension. A general impression of good writing is not a measurement. The rubric should be the same for the exercise and the live documents.", "A written English screen is a paid exercise that asks the candidate to produce a document from a realistic source. The exercise may include a customer reply, a note, or a short summary. The review records the task, the time allowed, the source, and the scoring. A timed test is a different instrument and should be validated separately.", "The unit is one candidate-assistant pair. The exercise is scored before hire, and the live documents are sampled after a fixed period. The review links the two scores without using the live score to change the exercise score. That separation keeps the comparison honest."]}, {"id": "evidence-collection", "heading": "Evidence collection", "paragraphs": ["Collect the exercise brief, the candidate's response, and the scoring sheet for every hired assistant in the sample. Collect three to five live documents from the first month, chosen before the reviewer sees the exercise score. Remove customer names and sensitive details. Keep the document type and the review date beside each sample.", "Ask the same reviewer to score the exercise and the live documents with the same rubric. If a second reviewer is available, have them score a subset without seeing the first score. Record the differences and discuss the standard before comparing candidates. A rubric that two reviewers cannot apply consistently is not ready.", "Record the onboarding the assistant received, including the tone guide, the examples, and the review cadence. A strong screen followed by weak onboarding can produce weak live work. The review should separate the effect of the screen from the effect of the support. Without that separation, the screen may be blamed or credited for the wrong thing."]}, {"id": "measuring-prediction", "heading": "Measuring prediction", "paragraphs": ["Compare the exercise score with the live score for each dimension. Look for dimensions where the two move together and dimensions where they do not. A screen that predicts structure but not factual accuracy is still useful if the role can review facts separately. Report the pattern rather than a single correlation.", "Check the cases where the exercise score was high and the live score was low. Read the documents and the onboarding notes to understand what changed. A common cause may be a missing template, a rushed review, or a task that the exercise did not represent. The exceptions are often more useful than the average.", "Check the cases where the exercise score was low and the live score was high. A candidate may have improved with the role's examples or may have been scored harshly on a style the client does not require. Review the original exercise with the current rubric. A screen that rejects good candidates is a cost even when it predicts the average."]}, {"id": "comparing-screen-designs", "heading": "Comparing screen designs", "paragraphs": ["Compare a timed exercise with an untimed one only if the role's work is genuinely time-bound. A timed test may measure speed and composure, while an untimed test measures the quality the client will review. The review should state which quality the role needs more. A fast reply that misses a fact is not a strong outcome for most support roles.", "Compare a generic writing prompt with a role-specific document task. A generic prompt is easier to administer but may not represent the actual work. A role-specific task is more predictive but requires a safe source and a paid reviewer. The comparison should include the cost of building and scoring each design.", "Compare a single exercise with a short paid follow-up. A single exercise is cheaper, while a follow-up can test a second document type. The review should state whether the added cost improved the prediction. A longer process is not automatically better if the first exercise already separates the candidates."]}, {"id": "limits-and-confounders", "heading": "Limits and confounders", "paragraphs": ["The sample of hired assistants is small in most teams, so a correlation can be unstable. Report the number of pairs and the range of scores rather than a precise coefficient. A pattern from five assistants is a prompt for a larger review, not a proven rule. The report should state the sample size beside every claim.", "The live documents are produced under different conditions from the exercise. The assistant may have a template, a reviewer, and a real deadline that changes the work. Those conditions are part of the role, not noise to be removed. The review should describe them before comparing the scores.", "The reviewer may remember the exercise score when reading the live documents. That memory can bias the live score toward the earlier judgment. Use a blind review or a second reviewer for the live sample. The evidence is stronger when the two scores are collected independently."]}, {"id": "reporting-the-finding", "heading": "Reporting the finding", "paragraphs": ["Report the dimensions the screen predicted, the dimensions it missed, and the cases that contradicted the pattern. Show one anonymized exercise and one live document that illustrate the finding. Recommend one change to the exercise or the rubric. Name the owner and the next review date.", "State the limits before the recommendation. A screen validated for one role and one client may not transfer to another. A finding that the exercise predicts structure but not facts is still useful because it tells the reviewer where to focus. Avoid claiming that the screen predicts overall performance.", "Recheck the next cohort with the revised exercise and the same rubric. Compare the new pairs with the old ones and look for the same pattern. If the prediction improves, keep the change and document the sample. If it does not, simplify the exercise rather than adding more scoring dimensions.", "Share the finding with the reviewers who score the exercise and the live work. A shared view of what the rubric measures is as important as the rubric itself. Read one pair together and discuss the difference before the next cohort. That conversation keeps the scoring from drifting between reviewers."]}, {"id": "practical-checklist", "heading": "Practical checklist", "paragraphs": ["Write the role's document standard before designing the exercise. Use one strong and one weak example from the actual work. Pay the candidate and keep the exercise under ninety minutes. Score substance before style.", "Score the exercise before reading the resume or the interview notes. Use a second reviewer for a subset. Keep the scores and the evidence. Compare the exercise with the first month of live documents.", "Review the exercise after each cohort and remove any dimension that does not predict the work. Keep the rubric short enough to apply consistently. A screen that helps the reviewer coach the role is more valuable than one that produces a perfect score. Read one sample with the reviewer after each change so the standard stays shared."]}]}];
